    except ValueError: raise argparse.ArgumentTypeError('integer required')
    if result<=0: raise argparse.ArgumentTypeError('positive required')
    return result
def parse(argv):
    argv=[('--token'if argument=='--tok'else argument)for argument in argv]
    p=argparse.ArgumentParser(allow_abbrev=False)
    p.add_argument('--output',required=True)
